SELECT [1ISIN].ISIN, Sum(FifoStock.AvQty) AS [In Stock], Sum(([Rt]/[PQty]*[AvQty])) AS Valore, Sum((([Rt]/[PQty]*[AvQty]))/[Change]![C_LAST_PRICE_REF ( LIVEQUOTE )]) AS Valueâ‚¬, IIf([Realtick]![C_LAST_PRICE_REF ( LIVEQUOTE )]=0,Sum([Realtick]![HST_CLOSE ( LIVEQUOTE )]*[AvQty]),Sum([Realtick]![C_LAST_PRICE_REF ( LIVEQUOTE )]*[AvQty])) AS ValueLive, IIf([Realtick]![C_LAST_PRICE_REF ( LIVEQUOTE )]=0,Sum([Realtick]![HST_CLOSE ( LIVEQUOTE )]*[AvQty]/[Change]![C_LAST_PRICE_REF ( LIVEQUOTE )]),Sum([Realtick]![C_LAST_PRICE_REF ( LIVEQUOTE )]*[AvQty]/[Change]![C_LAST_PRICE_REF ( LIVEQUOTE )])) AS ValueLiveâ‚¬, Change.[C_LAST_PRICE_REF ( LIVEQUOTE )] AS Change, [1ISIN].IdD, IIf([Realtick]![C_LAST_PRICE_REF ( LIVEQUOTE )]=0,(Sum([Realtick]![HST_CLOSE ( LIVEQUOTE )]*[AvQty]/[Change]![C_LAST_PRICE_REF ( LIVEQUOTE )]))*[leverage],(Sum([Realtick]![C_LAST_PRICE_REF ( LIVEQUOTE )]*[AvQty]/[Change]![C_LAST_PRICE_REF ( LIVEQUOTE )]))*[leverage]) AS ValLeverage, [1ISIN].Leverage, Realtick.[HST_CLOSE ( LIVEQUOTE )], Realtick.[C_LAST_PRICE_REF ( LIVEQUOTE )]
FROM Change INNER JOIN (Realtick RIGHT JOIN (FifoStock INNER JOIN 1ISIN ON FifoStock.Prdt = [1ISIN].ISIN) ON Realtick.[ISIN_NO ( LIVEQUOTE )] = [1ISIN].ISIN) ON Change.IdC = [1ISIN].IdC
GROUP BY [1ISIN].ISIN, Change.[C_LAST_PRICE_REF ( LIVEQUOTE )], [1ISIN].IdD, [1ISIN].Leverage, Realtick.[HST_CLOSE ( LIVEQUOTE )], Realtick.[C_LAST_PRICE_REF ( LIVEQUOTE )];
